package com.pocketpals.island;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.graphics.*;import android.media.*;import android.media.session.*;import android.os.*;import java.io.*;import java.util.Random;
/** Real, opt-in local rain playback. Media notifications are never used without audio. */
public class RainService extends Service {
 MediaPlayer player;MediaSession session;AudioManager audio;AudioFocusRequest focus;BroadcastReceiver noisy;Handler handler=new Handler(Looper.getMainLooper());boolean playing;
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"STOP".equals(i.getAction())){stopSelf();return START_NOT_STICKY;}if(playing)return START_NOT_STICKY;
 NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("rain","Rain playback",NotificationManager.IMPORTANCE_LOW));
 session=new MediaSession(this,"PocketPals rain");session.setCallback(new MediaSession.Callback(){public void onPause(){stopSelf();}public void onStop(){stopSelf();}});session.setActive(true);
 Bitmap pet=PetArt.bitmap(getSharedPreferences("pals",0).getInt("pet",0),0,"");session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,"Gentle rain with your PocketPal").putString(MediaMetadata.METADATA_KEY_ARTIST,"PocketPals Island").putBitmap(MediaMetadata.METADATA_KEY_ALBUM_ART,pet).putBitmap(MediaMetadata.METADATA_KEY_DISPLAY_ICON,pet).build());
 PendingIntent stop=PendingIntent.getService(this,31,new Intent(this,RainService.class).setAction("STOP"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);PendingIntent open=PendingIntent.getActivity(this,32,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);
 Notification n=new Notification.Builder(this,"rain").setSmallIcon(R.drawable.icon).setLargeIcon(pet).setContentTitle("Gentle rain with your PocketPal").setContentText("Local rain ambience · tap Stop to end").setContentIntent(open).setOngoing(true).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_pause,"Stop rain",stop).build()).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0)).build();
 if(Build.VERSION.SDK_INT>=29)startForeground(8,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK);else startForeground(8,n);
 audio=getSystemService(AudioManager.class);AudioAttributes attrs=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build();focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(attrs).setOnAudioFocusChangeListener(change->{if(change<0)stopSelf();}).build();
 if(audio.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){stopSelf();return START_NOT_STICKY;}
 try{File file=new File(getCacheDir(),"gentle-rain.wav");if(!file.exists())makeRain(file);player=new MediaPlayer();player.setAudioAttributes(attrs);player.setDataSource(file.getAbsolutePath());player.setLooping(true);player.setVolume(.35f,.35f);player.prepare();player.start();playing=true;session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_STOP).setState(PlaybackState.STATE_PLAYING,0,1).build());}catch(Exception e){stopSelf();return START_NOT_STICKY;}
 noisy=new BroadcastReceiver(){public void onReceive(Context c,Intent i){stopSelf();}};IntentFilter f=new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY);if(Build.VERSION.SDK_INT>=33)registerReceiver(noisy,f,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(noisy,f);handler.postDelayed(()->stopSelf(),30*60*1000L);return START_NOT_STICKY;
 }
 static void makeRain(File f)throws IOException{int rate=22050,count=rate*8,size=count*2;try(DataOutputStream out=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(f)))){out.writeBytes("RIFF");out.writeInt(Integer.reverseBytes(36+size));out.writeBytes("WAVEfmt ");out.writeInt(Integer.reverseBytes(16));out.writeShort(Short.reverseBytes((short)1));out.writeShort(Short.reverseBytes((short)1));out.writeInt(Integer.reverseBytes(rate));out.writeInt(Integer.reverseBytes(rate*2));out.writeShort(Short.reverseBytes((short)2));out.writeShort(Short.reverseBytes((short)16));out.writeBytes("data");out.writeInt(Integer.reverseBytes(size));Random r=new Random(21);double low=0;for(int k=0;k<count;k++){double white=r.nextDouble()*2-1;low=.97*low+.03*white;double fade=Math.min(1,Math.min(k/500.0,(count-1-k)/500.0));short sample=(short)((white*.15+low*.7)*15000*fade);out.writeShort(Short.reverseBytes(sample));}}}
 public void onDestroy(){handler.removeCallbacksAndMessages(null);if(noisy!=null)unregisterReceiver(noisy);if(player!=null){player.release();player=null;}if(session!=null){session.setPlaybackState(new PlaybackState.Builder().setState(PlaybackState.STATE_STOPPED,0,0).build());session.release();}if(audio!=null&&focus!=null)audio.abandonAudioFocusRequest(focus);stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
}
